import re


def validate_signup(data: dict) -> dict:
    """
    Validate and clean sign-up data.

    Required fields:
      - username: alphanumeric string
      - email: valid email address

    Optional fields:
      - plan: one of "free", "pro", "team" (default "free")
      - age: integer between 16 and 120 inclusive

    Unknown keys are dropped.

    Returns cleaned dict with default plan filled in.

    Raises ValueError with .messages dict on invalid input.
    """
    errors = {}
    cleaned = {}

    # Validate username (required, alphanumeric string)
    username = data.get("username")
    if username is None:
        errors["username"] = ["Missing data for required field."]
    elif not isinstance(username, str):
        errors["username"] = ["Must be a string."]
    elif not username.isalnum():
        errors["username"] = ["Must be alphanumeric."]
    else:
        cleaned["username"] = username

    # Validate email (required, valid email address)
    email = data.get("email")
    if email is None:
        errors["email"] = ["Missing data for required field."]
    elif not isinstance(email, str):
        errors["email"] = ["Must be a string."]
    else:
        # Simple RFC 5322-ish regex for email validation (not fully RFC compliant but practical)
        # This regex matches most common valid emails.
        email_pattern = re.compile(
            r"^[a-zA-Z0-9.!#$%&'*+/=?^_`{|}~-]+@[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}"
            r"[a-zA-Z0-9])?(?:\.[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?)*$"
        )
        if not email_pattern.match(email):
            errors["email"] = ["Invalid email address."]
        else:
            cleaned["email"] = email

    # Validate plan (optional, default "free", must be one of "free", "pro", "team")
    plan = data.get("plan", "free")
    if not isinstance(plan, str):
        errors["plan"] = ["Must be a string."]
    elif plan not in ("free", "pro", "team"):
        errors["plan"] = ['Must be one of "free", "pro", "team".']
    else:
        cleaned["plan"] = plan

    # Validate age (optional, integer 16 to 120 inclusive)
    if "age" in data:
        age = data["age"]
        if not isinstance(age, int):
            errors["age"] = ["Must be an integer."]
        elif not (16 <= age <= 120):
            errors["age"] = ["Must be between 16 and 120 inclusive."]
        else:
            cleaned["age"] = age

    if errors:
        exc = ValueError("Invalid input")
        exc.messages = errors
        raise exc

    return cleaned
